parameters.jsCode:
// Unwrap the MCP JSON-RPC envelope into the goal object.
const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
return { json: data.data ? data.data : data };

// area:coo:plan End branch — turn the plan goal's TICKED subtasks into real day tasks.
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const gql = async (query, variables) => {
  const args = variables !== undefined ? { query, variables } : { query };
  const resp = await helpers.httpRequest({
    method: 'POST', url: MCP,
    headers: { 'Content-Type': 'application/json', 'X-API-Key': RN },
    body: { jsonrpc: '2.0', method: 'tools/call', id: 1, params: { name: 'graphql_query', arguments: args } },
    json: true,
  });
  return JSON.parse(resp.result.content[0].text);
};

const g = $('Parse Goal').first().json.goalItemById || {};
const contribution = g.contribution || '';
const ticked = (g.subTasks || []).filter(s => s.isComplete);
if (!ticked.length) return [{ json: { ok: true, createdCount: 0, note: 'no ticked subtasks' } }];

// --- dates (US Eastern) — same convention as the plan Start: weeks run Saturday->Friday and each
// week goal is keyed by the week's FRIDAY. Use the COMING Friday (today if Friday, else next). ---
const nowE = $now.setZone('America/New_York');
const today = nowE.toFormat('dd-MM-yyyy');
const fwd = (5 - nowE.weekday + 7) % 7;
const weekStart = nowE.plus({ days: fwd }).toFormat('dd-MM-yyyy');

// --- this week's goals -> map trimmed routine name -> { taskRef, goalRef, tags, weekGoalBody } ---
const wg = (await gql('query{ goalDatePeriod(date:"' + weekStart + '",period:"week"){ goalItems{ id body taskRef goalRef tags routine{ id name } } } }')).data.goalDatePeriod;
const weekItems = (wg && wg.goalItems) || [];
const byRoutine = {};
for (const it of weekItems) {
  const rn = ((it.routine && it.routine.name) || '').trim().toLowerCase();
  if (!rn) continue;
  // link the day task to the routine's PARENT goal task = the week goal itself (its id),
  // so the task nests under it. (Using it.goalRef would link to the week goal's parent,
  // making the day task a sibling of the week goal instead of its child.)
  byRoutine[rn] = { taskRef: it.taskRef, weekGoalId: it.id, tags: it.tags || [], weekGoalBody: it.body || '' };
}

// --- idempotency: routines already carrying a plan:auto day task today ---
const dg = (await gql('query{ dailyGoals(date:"' + today + '"){ goalItems{ taskRef tags } } }')).data.dailyGoals;
const dgGroups = Array.isArray(dg) ? dg : (dg ? [dg] : []);
const plannedRefs = new Set();
for (const grp of dgGroups) for (const it of (grp.goalItems || [])) {
  if ((it.tags || []).includes('plan:auto') && it.taskRef) plannedRefs.add(it.taskRef);
}

// --- recover a subtask's detail section from the plan goal contribution (## <subBody>) ---
function sectionFor(subBody) {
  const parts = ('\n' + contribution).split('\n## ');
  for (const p of parts) {
    const nl = p.indexOf('\n');
    const head = (nl < 0 ? p : p.slice(0, nl)).trim();
    if (head === subBody) {
      const body = nl < 0 ? '' : p.slice(nl + 1);
      return body.split('\n').filter(l => {
        const t = l.trim();
        return t && !/^Routine:/.test(t) && !/^Week goal:/i.test(t) && !/^-{3,}$/.test(t);
      }).join('\n').trim();
    }
  }
  return '';
}

const ADD_REF = 'mutation($date:String!,$period:String!,$body:String,$contribution:String,$taskRef:String,$goalRef:String,$tags:[String]){ addGoalItem(date:$date,period:$period,body:$body,contribution:$contribution,taskRef:$taskRef,goalRef:$goalRef,tags:$tags,isComplete:false,isMilestone:true){ id } }';
const ADD_NOREF = 'mutation($date:String!,$period:String!,$body:String,$contribution:String,$taskRef:String,$tags:[String]){ addGoalItem(date:$date,period:$period,body:$body,contribution:$contribution,taskRef:$taskRef,tags:$tags,isComplete:false){ id } }';

const created = [], skipped = [], errors = [];
for (const s of ticked) {
  const subBody = String(s.body || '').trim();
  const m = subBody.match(/^\[(.+?)\]\s*([\s\S]*)$/);
  if (!m) { skipped.push({ sub: subBody, reason: 'no [routine] prefix' }); continue; }
  const routineName = m[1].trim();
  const title = m[2].trim();
  const r = byRoutine[routineName.toLowerCase()];
  if (!r || !title) { skipped.push({ sub: subBody, reason: 'routine not in this week goals' }); continue; }
  if (plannedRefs.has(r.taskRef)) { skipped.push({ sub: subBody, reason: 'already planned today' }); continue; }

  const desc = sectionFor(subBody);
  const contributionTxt = (desc ? desc + '\n\n' : '') + 'Routine: ' + routineName + '\nTowards week goal: ' + r.weekGoalBody;
  const tags = Array.from(new Set([...(r.tags || []), 'area:coo:execute', 'plan:auto']));
  const base = { date: today, period: 'day', body: title, contribution: contributionTxt, taskRef: r.taskRef, tags };
  const useRef = !!r.weekGoalId;
  const v = useRef ? { ...base, goalRef: r.weekGoalId } : base;
  try {
    const res = await gql(useRef ? ADD_REF : ADD_NOREF, v);
    if (res.errors) errors.push({ sub: subBody, error: res.errors[0].message });
    else { created.push({ routine: routineName, body: title, id: res.data.addGoalItem.id }); plannedRefs.add(r.taskRef); }
  } catch (e) { errors.push({ sub: subBody, error: String(e) }); }
  await new Promise(rs => setTimeout(rs, 400)); // avoid the addGoalItem lost-update race
}

return [{ json: { ok: true, today, weekStart, ticked: ticked.length,
  createdCount: created.length, created, skipped, errors } }];

// Execute (end of office work) — collect everything COMPLETED today under the trigger goal's
// routine (taskRef), straight from the app. No Jira calls: ticket keys are read off the work itself.
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const gql = async (query, variables) => {
  const args = variables !== undefined ? { query, variables } : { query };
  const resp = await helpers.httpRequest({
    method: 'POST', url: MCP,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + RN },
    body: { jsonrpc: '2.0', method: 'tools/call', id: 1, params: { name: 'graphql_query', arguments: args } },
    json: true,
  });
  return JSON.parse(resp.result.content[0].text);
};

const WORKDAY_HOURS = 8;
const SCRUM_HOURS = 2; // ceremonies are a fixed 2h block whenever they happened at all
const goalId = $('Webhook').first().json.query.goal_id;
const goal = $('Parse Goal').first().json.goalItemById || {};

// "Get Goal" does not select taskRef, and date/period come back null — re-read what we need.
const nowNy = $now.setZone('America/New_York');
let today = nowNy.toFormat('dd-MM-yyyy'), taskRef = goal.taskRef || null;
try {
  const gi = (await gql('query($id:ID!){ goalItemById(id:$id){ id date period taskRef } }', { id: goalId })).data.goalItemById;
  if (gi) { today = gi.date || today; taskRef = gi.taskRef || taskRef; }
} catch (e) {}

// --- today's DAY group only (dailyGoals also returns week/month/year groups) ---
let dayItems = [];
try {
  const dg = (await gql('query{ dailyGoals(date:"' + today + '"){ date period goalItems{ id body isComplete completedAt tags taskRef contribution subTasks{ id body isComplete } } } }')).data.dailyGoals;
  const groups = Array.isArray(dg) ? dg : (dg ? [dg] : []);
  const day = groups.find(g => g.period === 'day') || { goalItems: [] };
  dayItems = (day.goalItems || []).filter(g => g.taskRef === taskRef);
} catch (e) {}

const clean = (s, n) => String(s || '').replace(/\r/g, '').trim().slice(0, n);

// --- only the completed work: finished goals, plus finished subtasks of any goal ---
const activities = [];
for (const g of dayItems) {
  const doneSubs = (g.subTasks || []).filter(s => s.isComplete === true).map(s => clean(s.body, 200));
  if (g.isComplete === true) {
    activities.push({
      kind: 'task', body: clean(g.body, 200), tags: g.tags || [],
      notes: clean(g.contribution, 1500), completedSubtasks: doneSubs,
      completedAt: g.completedAt || null,
    });
  } else if (doneSubs.length) {
    // the parent is still open, but these subtasks are finished work and still count
    activities.push({
      kind: 'subtasks', body: clean(g.body, 200), tags: g.tags || [],
      notes: '', completedSubtasks: doneSubs, completedAt: null,
    });
  }
}
activities.sort((a, b) => (a.completedAt || 0) - (b.completedAt || 0));

// --- ticket keys, read off the completed work (no Jira lookup) ---
const KEY_RE = /\b([A-Z][A-Z0-9]{1,9}-\d+)\b/g;
const keyCount = {};
for (const a of activities) {
  const hay = [a.body, a.notes].concat(a.completedSubtasks).join(' \n ');
  const found = hay.match(KEY_RE) || [];
  for (const k of found) keyCount[k] = (keyCount[k] || 0) + 1;
}
const ticketKeys = Object.keys(keyCount);

// --- prompt ---
const systemPrompt =
  'You are the COO end-of-day agent for a senior front-end engineer at an enterprise e-commerce programme. ' +
  'You are given ONLY the work the engineer actually COMPLETED today. Turn it into the three artefacts they must file. ' +
  'Use only what is in the input — never invent tickets, meetings or work that is not there. ' +
  'If the input reports that nothing was completed, that is a real answer: return ' +
  '{"sre":[],"scrum":{"yesterday":"","today":"","blockers":""},"tempo":[],' +
  '"timesheet":{"development":0,"testing":0,"operations":0,"monitoring":0,"management":0}} ' +
  'and invent NOTHING — the goal title alone is not evidence of work done. ' +
  'Return STRICT JSON only, no prose:\n' +
  '{"sre":["<exactly 5 bullets for the team SRE/status Confluence page: outcome-first, past tense, ' +
  'each <= 160 chars, naming the ticket key when the input has one>"],' +
  '"scrum":{"yesterday":"<1-2 sentences: what was completed today, for tomorrow\'s standup>",' +
  '"today":"<1-2 sentences: the obvious next step>","blockers":"<blockers named in the input, or \'None\'>"},' +
  '"tempo":[{"ticket":"<ticket key from the input, or \\"Scrum\\" for ceremonies/standup/meetings>",' +
  '"description":"<worklog comment, <= 120 chars>","hours":<number>}],' +
  '"timesheet":{"development":<number>,"testing":<number>,"operations":<number>,"monitoring":<number>,"management":<number>}}\n' +
  'Rules: give one tempo entry per distinct ticket key found, plus exactly one "Scrum" entry covering standups, ' +
  'refinement and meetings evidenced in the input — ONLY if the input actually evidences ceremonies. ' +
  'When that "Scrum" entry is present it is always exactly ' + SCRUM_HOURS + ' hours and the remaining ' +
  (WORKDAY_HOURS - SCRUM_HOURS) + ' hours are spread across the ticket entries. Tempo hours must total ' + WORKDAY_HOURS + '. ' +
  'Timesheet values must also total ' + WORKDAY_HOURS + ' and split the SAME day across the five Coforge categories: ' +
  'development (coding, PRs, refactors), testing (tests, QA, verification), operations (releases, pipelines, ' +
  'dependency/vulnerability work), monitoring (dashboards, analytics, alerts, audits), management (standups, ' +
  'meetings, planning, specs, reviews of others). Use 0 for a category with no evidence.';

const lines = activities.map((a, i) =>
  (i + 1) + '. [' + a.kind + '] ' + a.body + (a.tags.length ? '  (' + a.tags.join(', ') + ')' : '') +
  (a.completedSubtasks.length ? '\n   completed:\n' + a.completedSubtasks.map(s => '     - ' + s).join('\n') : '') +
  (a.notes ? '\n   notes:\n     ' + a.notes.split('\n').join('\n     ') : ''));

const userMessage =
  'Date: ' + nowNy.toFormat('cccc, dd LLLL yyyy') + '\n' +
  'Routine block: ' + (goal.body ? goal.body : 'Office work') + '\n' +
  (ticketKeys.length ? 'Ticket keys present in today\'s completed work: ' + ticketKeys.join(', ') + '\n' : '') +
  '\nCOMPLETED TODAY (' + activities.length + ' item(s)):\n\n' +
  (lines.length ? lines.join('\n\n') : '(nothing was marked complete today)');

return [{ json: {
  systemPrompt, userMessage,
  wrap: { today, goalId, taskRef, workdayHours: WORKDAY_HOURS, scrumHours: SCRUM_HOURS, ticketKeys, activities,
          activityCount: activities.length, routineBody: goal.body || '' },
} }];

// Execute (end of office work) — turn the model's JSON into one copy-paste HTML sheet and store it
// on the goal's REWARD. body and contribution are never written by this branch.
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const gql = async (query, variables) => {
  const resp = await helpers.httpRequest({
    method: 'POST', url: MCP,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + RN },
    body: { jsonrpc: '2.0', method: 'tools/call', id: 1, params: { name: 'graphql_query', arguments: { query, variables } } },
    json: true,
  });
  return JSON.parse(resp.result.content[0].text);
};

const wrap = $('Execute: Collect Activity').first().json.wrap;
const TOTAL = wrap.workdayHours;
const SCRUM_HOURS = wrap.scrumHours;

// --- parse the model's JSON ---
const raw = $input.first().json;
let content = '{}';
try { content = raw.choices[0].message.content; } catch (e) {}
let parsed;
try { parsed = JSON.parse(content); }
catch (e) { const m = content && content.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : {}; }

const CATS = ['development', 'testing', 'operations', 'monitoring', 'management'];
const hasWork = wrap.activityCount > 0;

// Nothing completed means nothing to report. Without this the model happily writes a status
// update out of the goal's title alone, which would file fiction into a real Confluence page.
const sre = hasWork ? (parsed.sre || []).map(s => String(s).trim()).filter(Boolean).slice(0, 5) : [];
const scrum = hasWork ? (parsed.scrum || {}) : {};

// --- hours are normalised here, not trusted from the model: exact totals, quarter-hour steps ---
const round25 = (n) => Math.round(n * 4) / 4;
const normalise = (values, total) => {
  const nums = values.map(v => (Number(v) > 0 ? Number(v) : 0));
  let sum = nums.reduce((a, b) => a + b, 0);
  const base = sum > 0 ? nums : nums.map(() => 1); // no signal at all -> split evenly
  sum = base.reduce((a, b) => a + b, 0);
  const scaled = base.map(v => round25((v * total) / sum));
  const drift = round25(total - scaled.reduce((a, b) => a + b, 0));
  if (drift !== 0 && scaled.length) {
    let i = 0; for (let j = 1; j < scaled.length; j++) if (scaled[j] > scaled[i]) i = j;
    scaled[i] = Math.max(0, round25(scaled[i] + drift));
  }
  return scaled;
};

let tempo = (parsed.tempo || [])
  .map(t => ({ ticket: String((t && t.ticket) || '').trim() || 'Scrum',
               description: String((t && t.description) || '').trim(),
               hours: Number(t && t.hours) || 0 }))
  .filter(t => t.description || t.ticket);
// Ceremonies are a fixed block, not something the model gets to estimate: when a Scrum row exists it
// is pinned to SCRUM_HOURS and only the ticket rows share the rest of the day.
const isScrum = (t) => /scrum|stand[- ]?up|ceremon|meeting|refinement/i.test(t.ticket);
if (hasWork && tempo.length) {
  const si = tempo.findIndex(isScrum);
  if (si === -1) {
    const h = normalise(tempo.map(t => t.hours), TOTAL);
    tempo = tempo.map((t, i) => ({ ...t, hours: h[i] }));
  } else {
    const others = tempo.filter((_, i) => i !== si);
    // with nothing else logged, the ceremony block is the whole day rather than a 2h short day
    const scrumHours = others.length ? Math.min(SCRUM_HOURS, TOTAL) : TOTAL;
    const h = others.length ? normalise(others.map(t => t.hours), round25(TOTAL - scrumHours)) : [];
    let k = 0;
    tempo = tempo.map((t, i) => (i === si ? { ...t, hours: scrumHours } : { ...t, hours: h[k++] }));
  }
  tempo = tempo.filter(t => t.hours > 0);
} else { tempo = []; }

let timesheet = CATS.map(c => ({ category: c, hours: Number((parsed.timesheet || {})[c]) || 0 }));
if (hasWork) {
  const h = normalise(timesheet.map(t => t.hours), TOTAL);
  timesheet = timesheet.map((t, i) => ({ ...t, hours: h[i] }));
} else { timesheet = timesheet.map(t => ({ ...t, hours: 0 })); }

const sum = (rows) => rows.reduce((a, r) => a + r.hours, 0);
const hrs = (n) => (Math.round(n * 100) / 100).toString();

// --- HTML (self-contained, inline styles: it is stored and re-rendered inside the app) ---
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const S = {
  card: 'border:1px solid #d7dce3;border-radius:10px;margin:0 0 18px;overflow:hidden;background:#fff',
  head: 'background:#f4f6f9;border-bottom:1px solid #d7dce3;padding:10px 14px;font:600 14px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;color:#1b2430',
  hint: 'font:400 12px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;color:#5b6673;margin:2px 0 0',
  body: 'padding:14px',
  pre:  'background:#0f172a;color:#e2e8f0;padding:12px;border-radius:8px;overflow-x:auto;white-space:pre;font:13px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;margin:10px 0 0',
  th:   'text-align:left;padding:8px 10px;border-bottom:2px solid #d7dce3;font:600 13px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;color:#1b2430',
  td:   'padding:8px 10px;border-bottom:1px solid #eef1f5;font:13px/1.5 -apple-system,Segoe UI,Roboto,sans-serif;color:#26303c;vertical-align:top',
  num:  'padding:8px 10px;border-bottom:1px solid #eef1f5;font:600 13px/1.5 ui-monospace,Menlo,monospace;color:#26303c;text-align:right;white-space:nowrap',
};
// several call sites append an extra declaration (S.th + 'text-align:right'), so every base
// style must end in a semicolon or the two declarations fuse into one invalid rule.
Object.keys(S).forEach(k => { if (!/;\s*$/.test(S[k])) S[k] += ';'; });
const card = (title, hint, inner) =>
  '<section style="' + S.card + '"><div style="' + S.head + '">' + esc(title) +
  (hint ? '<div style="' + S.hint + '">' + esc(hint) + '</div>' : '') + '</div>' +
  '<div style="' + S.body + '">' + inner + '</div></section>';

const sreHtml = sre.length
  ? '<ul style="margin:0;padding-left:20px;font:14px/1.65 -apple-system,Segoe UI,Roboto,sans-serif;color:#26303c">' +
    sre.map(b => '<li>' + esc(b) + '</li>').join('') + '</ul>' +
    '<pre style="' + S.pre + '">' + esc(sre.map(b => '• ' + b).join('\n')) + '</pre>'
  : '<p style="' + S.hint + '">Nothing was marked complete today, so there is nothing to file. ' +
    'Tick your completed tasks and re-run.</p>';

const tempoHtml = tempo.length
  ? '<table style="width:100%;border-collapse:collapse"><tr><th style="' + S.th + '">Ticket</th>' +
    '<th style="' + S.th + '">Worklog description</th><th style="' + S.th + 'text-align:right">Hours</th></tr>' +
    tempo.map(t => '<tr><td style="' + S.td + '"><strong>' + esc(t.ticket) + '</strong></td><td style="' + S.td + '">' +
      esc(t.description) + '</td><td style="' + S.num + '">' + hrs(t.hours) + '</td></tr>').join('') +
    '<tr><td style="' + S.td + 'font-weight:600">Total</td><td style="' + S.td + '"></td><td style="' + S.num + '">' +
      hrs(sum(tempo)) + '</td></tr></table>' +
    '<pre style="' + S.pre + '">' + esc(tempo.map(t => t.ticket + '\t' + hrs(t.hours) + '\t' + t.description).join('\n')) + '</pre>'
  : '<p style="' + S.hint + '">No completed ticket work to log.</p>';

const timesheetHtml =
  '<table style="width:100%;border-collapse:collapse"><tr><th style="' + S.th + '">Category</th>' +
  '<th style="' + S.th + 'text-align:right">Hours</th></tr>' +
  timesheet.map(t => '<tr><td style="' + S.td + '">' + esc(t.category.charAt(0).toUpperCase() + t.category.slice(1)) +
    '</td><td style="' + S.num + '">' + hrs(t.hours) + '</td></tr>').join('') +
  '<tr><td style="' + S.td + 'font-weight:600">Total</td><td style="' + S.num + '">' + hrs(sum(timesheet)) + '</td></tr></table>' +
  '<pre style="' + S.pre + '">' + esc(timesheet.map(t => t.category + '\t' + hrs(t.hours)).join('\n')) + '</pre>';

const scrumHtml =
  '<p style="margin:0 0 8px;font:14px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;color:#26303c">' +
  '<strong>Done:</strong> ' + esc(scrum.yesterday || '—') + '<br>' +
  '<strong>Next:</strong> ' + esc(scrum.today || '—') + '<br>' +
  '<strong>Blockers:</strong> ' + esc(scrum.blockers || 'None') + '</p>';

const html =
  '<div style="max-width:860px;margin:0 auto;padding:16px;background:#eef1f5">' +
  '<div style="' + S.card + 'padding:14px 16px">' +
  '<div style="font:700 18px/1.3 -apple-system,Segoe UI,Roboto,sans-serif;color:#0f172a">Daily wrap — ' + esc(wrap.today) + '</div>' +
  '<div style="' + S.hint + '">Copy each block below into its destination. Built from the ' +
  esc(String(wrap.activityCount)) + ' item(s) you completed today' +
  (wrap.ticketKeys.length ? ' · tickets: ' + esc(wrap.ticketKeys.join(', ')) : '') + '.</div></div>' +
  card('1 · SRE Confluence page', 'Paste these 5 bullets into today\'s SRE page.', sreHtml) +
  card('2 · Tempo worklogs', 'Log each row in Tempo (ticket · hours · description). Copy block is tab-separated.', tempoHtml + scrumHtml) +
  card('3 · Coforge timesheet', 'Enter these hours against the five categories. Copy block is tab-separated.', timesheetHtml) +
  '</div>';

// --- store on REWARD only; body and contribution are left untouched ---
const errors = [];
try {
  const res = await gql('mutation($id:ID!,$reward:String){ updateGoalItemReward(id:$id,reward:$reward){ id } }',
                        { id: wrap.goalId, reward: html });
  if (res.errors) errors.push(res.errors[0].message);
} catch (e) { errors.push(String(e)); }

return [{ json: {
  ok: errors.length === 0,
  date: wrap.today, goalId: wrap.goalId, taskRef: wrap.taskRef,
  activityCount: wrap.activityCount, ticketKeys: wrap.ticketKeys,
  sreBullets: sre.length, tempoEntries: tempo.length,
  tempoHours: sum(tempo), timesheetHours: sum(timesheet),
  timesheet: timesheet.reduce((o, t) => (o[t.category] = t.hours, o), {}),
  errors, html,
} }];

// Reflect (last routine of the day) — pull the whole day together from Routine Notes + chess.com
// and hand the LLM only judgement calls (headline, COO feedback scores, soul line, 4 MCQs).
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const gql = async (query, variables) => {
  const args = variables !== undefined ? { query, variables } : { query };
  const resp = await helpers.httpRequest({
    method: 'POST', url: MCP,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + RN },
    body: { jsonrpc: '2.0', method: 'tools/call', id: 1, params: { name: 'graphql_query', arguments: args } },
    json: true,
  });
  return JSON.parse(resp.result.content[0].text);
};

const goalId = $('Webhook').first().json.query.goal_id;
const goal = $('Parse Goal').first().json.goalItemById || {};
const nowE = $now.setZone('America/New_York');
const clip = (s, n) => String(s || '').replace(/\r/g, '').trim().slice(0, n);

// Resolve the goal's REAL day bucket (goalItemById returns null date/period), so a re-run
// for yesterday's goal reflects yesterday, not whatever day the re-run happens on.
let today = goal.date || nowE.toFormat('dd-MM-yyyy');
try {
  const gi = (await gql('query{ goalItemById(id:"' + goalId + '"){ date taskRef } }')).data.goalItemById || {};
  if (gi.date) today = gi.date;
  else if (gi.taskRef) {
    const mt = (await gql('query{ monthTaskGoals(date:"' + nowE.toFormat('dd-MM-yyyy') + '",taskRef:"' + gi.taskRef + '"){ date period goalItems{ id } } }')).data.monthTaskGoals || [];
    for (const grp of (Array.isArray(mt) ? mt : [mt])) {
      if (grp && grp.period === 'day' && (grp.goalItems || []).some(g => g.id === goalId)) { today = grp.date; break; }
    }
  }
} catch (e) {}
const dref = DateTime.fromFormat(today, 'dd-MM-yyyy', { zone: 'America/New_York' });

// ---- Row 1: D/K/G stimuli + routine tick timing ----
let dkg = null, week = [];
try {
  week = (await gql('query{ weekStimuli(date:"' + today + '"){ date D K G } }')).data.weekStimuli || [];
  dkg = week.find(w => w.date === today) || null;
} catch (e) {}
let routines = [];
try {
  const rd = (await gql('query{ routineDate(date:"' + today + '"){ tasklist{ id name time points ticked passed redeemed passedPoints tags } } }')).data.routineDate;
  routines = ((rd && rd.tasklist) || []).slice().sort((a, b) => String(a.time).localeCompare(String(b.time)));
} catch (e) {}
const rlite = r => ({ name: String(r.name || '').trim(), time: r.time, points: r.points });
// passed:true = the routine's window had already PASSED and points were used to tick it
// (those rows carry redeemed/passedPoints) -> OUT of time. A plain tick (passed:false) is in time.
const inTime = routines.filter(r => r.ticked && !r.passed).map(rlite);
const outTime = routines.filter(r => r.ticked && r.passed).map(rlite);
const missed = routines.filter(r => !r.ticked).map(rlite);
let xp = null;
try { xp = (await gql('query{ xpBalance{ earned used available pendingToday } }')).data.xpBalance; } catch (e) {}

// ---- day goals, bucketed by area tag ----
let dayItems = [];
try {
  const dg = (await gql('query{ dailyGoals(date:"' + today + '"){ date period goalItems{ id body isComplete completedAt tags taskRef contribution reward subTasks{ id body isComplete } } } }')).data.dailyGoals;
  const groups = Array.isArray(dg) ? dg : (dg ? [dg] : []);
  dayItems = ((groups.find(g => g.period === 'day') || {}).goalItems) || [];
} catch (e) {}
// task-level time management: a completed day task is "in time" if it was ticked (completedAt,
// epoch ms) on the same day and before its routine's window closed — the window runs from the
// routine's start to the next routine's start; the last window runs to midnight Eastern.
const windows = {};
for (let i = 0; i < routines.length; i++) {
  const nxt = routines[i + 1];
  const hm = String((nxt || {}).time || '').split(':');
  const end = nxt ? dref.set({ hour: Number(hm[0]) || 0, minute: Number(hm[1]) || 0, second: 0, millisecond: 0 })
                  : dref.plus({ days: 1 }).startOf('day');
  windows[routines[i].id] = { name: String(routines[i].name || '').trim(), time: routines[i].time, end };
}
const tasksInTime = [], tasksOutTime = [];
for (const g of dayItems) {
  if (g.isComplete !== true || !g.completedAt) continue;
  const w = windows[g.taskRef];
  if (!w) continue;
  const at = DateTime.fromMillis(Number(g.completedAt)).setZone('America/New_York');
  const sameDay = at.toFormat('dd-MM-yyyy') === today;
  const rec = { body: clip(g.body, 90), routine: w.name, at: at.toFormat('HH:mm'), sameDay };
  (sameDay && at < w.end ? tasksInTime : tasksOutTime).push(rec);
}

const byTag = t => dayItems.filter(g => (g.tags || []).includes(t));
const lite = g => g ? { body: clip(g.body, 160), isComplete: g.isComplete === true,
                        contribution: clip(g.contribution, 700), reward: clip(g.reward, 300),
                        subs: (g.subTasks || []).map(s => ({ body: clip(s.body, 120), done: s.isComplete === true })) } : null;

// Row 2 — CEO
const ceo = { mind: lite(byTag('area:ceo:mind')[0]), body: lite(byTag('area:ceo:body')[0]), soul: lite(byTag('area:ceo:soul')[0]) };

// chess.com alertness (public API, no auth). Failure just leaves the tile empty.
let chess = null;
try {
  const UA = { 'User-Agent': 'reflect-dashboard (workflows.grvpanchal.me)' };
  const stats = await helpers.httpRequest({ url: 'https://api.chess.com/pub/player/grvpanchal/stats', json: true, headers: UA, timeout: 15000 });
  const last = k => (stats[k] && stats[k].last && stats[k].last.rating) || null;
  chess = { rapid: last('chess_rapid'), blitz: last('chess_blitz'), bullet: last('chess_bullet'),
            puzzle: (stats.tactics && stats.tactics.highest && stats.tactics.highest.rating) || null };
  const games = await helpers.httpRequest({ url: 'https://api.chess.com/pub/player/grvpanchal/games/' + dref.toFormat('yyyy/MM'), json: true, headers: UA, timeout: 15000 });
  const dayStart = dref.startOf('day').toSeconds();
  const dayEnd = dref.plus({ days: 1 }).startOf('day').toSeconds();
  let w = 0, l = 0, d = 0, n = 0;
  for (const g of (games.games || [])) {
    if (!g.end_time || g.end_time < dayStart || g.end_time >= dayEnd) continue;
    n++;
    const me = String((g.white || {}).username || '').toLowerCase() === 'grvpanchal' ? g.white : g.black;
    const res = (me || {}).result || '';
    if (res === 'win') w++;
    else if (['agreed', 'repetition', 'stalemate', 'insufficient', '50move', 'timevsinsufficient'].indexOf(res) >= 0) d++;
    else l++;
  }
  chess.today = { games: n, wins: w, losses: l, draws: d };
} catch (e) {}

// nutrition via the mfp wrapper container (same docker network as n8n), pinned to the
// resolved day bucket so re-runs report that day's diary. Cookie expiry -> 502 -> tile falls to TBD.
let nutrition = null;
try {
  const mfp = await helpers.httpRequest({
    method: 'GET', url: 'http://mfp:8000/diary?date=' + dref.toFormat('yyyy-MM-dd'),
    headers: { 'X-API-Key': '<<REPLACE_ME>>' },
    json: true, timeout: 20000,
  });
  const t = mfp.totals || {}, gl = mfp.goals || {};
  const rnd = v => (v === null || v === undefined ? null : Math.round(Number(v)));
  nutrition = { calories: rnd(t.calories), caloriesGoal: rnd(gl.calories),
                protein: rnd(t.protein), proteinGoal: rnd(gl.protein),
                carbs: rnd(t.carbohydrates), fat: rnd(t.fat) };
} catch (e) {}

// Row 3 — COO
const cooDefine = lite(byTag('area:coo:define')[0]);
const cooPlan = lite(byTag('area:coo:plan')[0]);
const execItems = byTag('area:coo:execute');
const execDone = execItems.filter(g => g.isComplete === true);
let subsTotal = 0, subsDone = 0;
for (const g of execItems) for (const s of (g.subTasks || [])) { subsTotal++; if (s.isComplete === true) subsDone++; }
const coo = { define: cooDefine, plan: cooPlan,
              exec: { total: execItems.length, done: execDone.length, subsTotal, subsDone,
                      items: execItems.map(g => ({ body: clip(g.body, 120), done: g.isComplete === true })) } };

// Row 4 — CTO: ticket keys off the Jira goal's completed subtasks
const jira = dayItems.find(g => (g.tags || []).includes('project:jira')) || null;
const KEY_RE = /\b([A-Z][A-Z0-9]{1,9}-\d+)\b/;
const tickets = { done: [], open: [] };
for (const s of ((jira || {}).subTasks || [])) {
  const m = String(s.body || '').match(KEY_RE);
  const entry = { key: m ? m[1] : null, body: clip(s.body, 110) };
  (s.isComplete === true ? tickets.done : tickets.open).push(entry);
}
const cto = { hasJira: !!jira, tickets };

// Row 5 — CIO: parse the Leverage Report markdown table out of the cio goal contribution
const cioGoal = byTag('area:cio')[0] || null;
const lev = {};
if (cioGoal && cioGoal.contribution) {
  for (const line of String(cioGoal.contribution).split('\n')) {
    const m = line.match(/^\s*\|\s*(Tech|Labou?r|Capital|Media)\s*\|\s*([^|]*)\|\s*([^|]*)\|/i);
    if (m) {
      const k = m[1].toLowerCase().replace('labour', 'labor');
      if (!lev[k]) lev[k] = { entity: m[2].trim(), value: m[3].trim() };
    }
  }
}
const cio = { goal: cioGoal ? { body: clip(cioGoal.body, 120), done: cioGoal.isComplete === true } : null, lev };

// Row 6 — CFO: stage heading + fw-logo iframe straight out of the cfo goal contribution
const cfoGoal = byTag('area:cfo')[0] || null;
let cfoStage = null, cfoIframe = null;
if (cfoGoal && cfoGoal.contribution) {
  const m = String(cfoGoal.contribution).match(/Financial Stage:\s*([^\n]+)/i);
  if (m) cfoStage = m[1].trim();
  const f = String(cfoGoal.contribution).match(/<iframe[^>]*src="([^"]+)"/i);
  if (f) cfoIframe = f[1];
}
const cfo = { goal: cfoGoal ? { body: clip(cfoGoal.body, 120), done: cfoGoal.isComplete === true,
                                subs: (cfoGoal.subTasks || []).map(s => ({ body: clip(s.body, 100), done: s.isComplete === true })) } : null,
              stage: cfoStage, iframe: cfoIframe };

// Rows 7/8 — CXO + CMO (mostly TBD tiles, but surface what the day recorded)
const cxoGoal = byTag('area:cxo')[0] || null;
const cmoGoal = byTag('area:cmo')[0] || null;
let chDone = 0, chTotal = 0;
for (const s of ((cmoGoal || {}).subTasks || [])) { chTotal++; if (s.isComplete === true) chDone++; }
const cxo = { goal: cxoGoal ? lite(cxoGoal) : null };
const cmo = { goal: cmoGoal ? { body: clip(cmoGoal.body, 120), done: cmoGoal.isComplete === true } : null, chDone, chTotal };

// ---- LLM prompt: judgement only, numbers stay code-computed ----
const systemPrompt =
  'You are the COO reflection agent closing out the day for a solo founder-operator running a ' +
  'C-suite personal operating system (CEO body/mind/soul, COO define/plan/execute, CTO, CIO, CFO, CMO, CXO). ' +
  'You get ONLY what actually happened today. Never invent events, numbers or work. ' +
  'Return STRICT JSON, no prose:\n' +
  '{"headline":"<one-sentence verdict on the day, direct second person, <=140 chars>",' +
  '"coo":{"defineAlignment":{"score":<0-10>,"note":"<how well the define insight matched what the day became, <=140 chars>"},' +
  '"planRelevance":{"score":<0-10>,"note":"<did the plan propose the right work, was it ticked and materialised, <=140 chars>"},' +
  '"executionEfficiency":{"score":<0-10>,"note":"<completed vs planned + routine timing, <=140 chars>"}},' +
  '"soul":{"thought":"<one progressive thought for tomorrow, grounded in today, <=160 chars>"},' +
  '"mcq":[{"question":"<reflection question about today\'s management performance>",' +
  '"options":["<option A>","<option B>","<option C>","<option D>"],"answer":<0-3>,"why":"<why that answer fits today, <=140 chars>"}]}\n' +
  'Rules: the top-level keys are EXACTLY headline, coo, soul, mcq — mcq is a TOP-LEVEL array, never nested. ' +
  'Exactly 4 mcq entries, each anchored to a concrete fact from the input (a routine that slipped, ' +
  'a task left open, a score, a win). Options must be plausible self-assessments, one clearly best. ' +
  'Scores reflect the evidence: an unticked plan or mostly-missed routines cannot score high.';

const line = (label, v) => label + ': ' + (v === null || v === undefined ? 'n/a' : v);
const goalLine = (label, g) => label + ': ' + (g ? '"' + g.body + '" — ' + (g.isComplete || g.done ? 'COMPLETED' : 'NOT completed') : 'none today');
const userMessage = [
  'Date: ' + dref.toFormat('cccc, dd LLLL yyyy'),
  '',
  '== Routine analytics ==',
  line('Stimuli D (Discipline)', dkg && dkg.D), line('Stimuli K (Kinetics)', dkg && dkg.K), line('Stimuli G (Geniuses)', dkg && dkg.G),
  'Routines ticked IN time: ' + (inTime.map(r => r.name + ' @' + r.time).join(', ') || 'none'),
  'Routines ticked OUT of time: ' + (outTime.map(r => r.name + ' @' + r.time).join(', ') || 'none'),
  'Routines not ticked: ' + (missed.map(r => r.name + ' @' + r.time).join(', ') || 'none'),
  'Day tasks done IN their routine window: ' + (tasksInTime.map(t => t.body + ' (' + t.routine + ', ' + t.at + ')').join('; ') || 'none'),
  'Day tasks done OUT of their routine window: ' + (tasksOutTime.map(t => t.body + ' (' + t.routine + ', done ' + t.at + (t.sameDay ? '' : ' next day') + ')').join('; ') || 'none'),
  '',
  '== COO ==',
  goalLine('Define goal (morning insight)', cooDefine),
  cooDefine && cooDefine.contribution ? 'Define insight: ' + clip(cooDefine.contribution, 500) : '',
  goalLine('Plan goal', cooPlan),
  cooPlan ? 'Plan subtasks ticked: ' + cooPlan.subs.filter(s => s.done).length + '/' + cooPlan.subs.length : '',
  'Execute day tasks completed: ' + coo.exec.done + '/' + coo.exec.total + ' (subtasks ' + subsDone + '/' + subsTotal + ')',
  coo.exec.items.map(t => ' - [' + (t.done ? 'x' : ' ') + '] ' + t.body).join('\n'),
  '',
  '== CTO ==',
  'Jira tickets completed today: ' + (tickets.done.map(t => t.key || t.body).join(', ') || 'none') +
    (tickets.open.length ? ' | still open: ' + tickets.open.map(t => t.key || t.body).join(', ') : ''),
  '',
  '== CEO ==',
  goalLine('Mind', ceo.mind), goalLine('Body', ceo.body), goalLine('Soul', ceo.soul),
  chess && chess.today ? 'Chess today: ' + chess.today.games + ' games (' + chess.today.wins + 'W/' + chess.today.losses + 'L/' + chess.today.draws + 'D), rapid ' + (chess.rapid || '?') : '',
  nutrition ? 'Nutrition (MyFitnessPal): ' + (nutrition.calories || 0) + '/' + (nutrition.caloriesGoal || '?') + ' kcal, protein ' + (nutrition.protein || 0) + '/' + (nutrition.proteinGoal || '?') + 'g' : '',
  '',
  '== Other desks ==',
  'CIO leverage: ' + (Object.keys(lev).map(k => k + '=' + lev[k].value).join(', ') || 'no report today'),
  line('CFO stage', cfoStage),
  goalLine('CXO', cxo.goal), goalLine('CMO', cmo.goal),
  cmo.goal ? 'CMO channels shipped: ' + chDone + '/' + chTotal : '',
].filter(Boolean).join('\n');

return [{ json: { systemPrompt, userMessage,
  day: { today, goalId, dkg, week, inTime, outTime, missed, tasksInTime, tasksOutTime, xp, chess, nutrition, ceo, coo, cto, cio, cfo, cxo, cmo } } }];

// Reflect — turn code-computed day data + the model's judgement into the 8-row dashboard,
// store it on the trigger goal's REWARD, and pass the HTML on to the responder.
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const gql = async (query, variables) => {
  const resp = await helpers.httpRequest({
    method: 'POST', url: MCP,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + RN },
    body: { jsonrpc: '2.0', method: 'tools/call', id: 1, params: { name: 'graphql_query', arguments: { query, variables } } },
    json: true,
  });
  return JSON.parse(resp.result.content[0].text);
};

const day = $('Reflect: Collect Day').first().json.day;

// ---- model JSON (same defensive parse as the execute wrap) ----
const raw = $input.first().json;
let content = '{}';
try { content = raw.choices[0].message.content; } catch (e) {}
const tryParse = (s) => { try { return JSON.parse(s); } catch (e) { return null; } };
let ai = tryParse(content);
if (!ai) { const m = content && content.match(/\{[\s\S]*\}/); if (m) ai = tryParse(m[0]); }
if (!ai && content && content.indexOf('{') >= 0) {
  // models sometimes drop the last closing brace(s): rebalance outside of strings and retry
  let s = content.slice(content.indexOf('{'));
  const stack = []; let inStr = false, escp = false;
  for (const c of s) {
    if (escp) { escp = false; continue; }
    if (inStr) { if (c === '\\') escp = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true;
    else if (c === '{') stack.push('}');
    else if (c === '[') stack.push(']');
    else if (c === '}' || c === ']') stack.pop();
  }
  if (inStr) s += '"';
  while (stack.length) s += stack.pop();
  ai = tryParse(s);
}
if (!ai) ai = {};
const aiCoo = ai.coo || {};
const score = (o) => { const n = Number((o || {}).score); return isFinite(n) ? Math.max(0, Math.min(10, n)) : null; };
// mcq belongs at the top level, but the model sometimes nests it under soul/coo
let mcqRaw = ai.mcq;
if (!Array.isArray(mcqRaw)) for (const k of ['soul', 'coo', 'reflect']) {
  if (ai[k] && Array.isArray(ai[k].mcq)) { mcqRaw = ai[k].mcq; break; }
}
const mcq = (Array.isArray(mcqRaw) ? mcqRaw : []).slice(0, 4)
  .filter(q => q && q.question && Array.isArray(q.options) && q.options.length >= 2);

// ---- shared styles (same shell as the execute wrap; single accent hue for meters,
// status colors only beside their icon+label, ink tokens for all text) ----
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const FONT = '-apple-system,Segoe UI,Roboto,sans-serif';
const S = {
  card: 'border:1px solid #d7dce3;border-radius:10px;margin:0 0 18px;overflow:hidden;background:#fff',
  head: 'background:#f4f6f9;border-bottom:1px solid #d7dce3;padding:10px 14px;font:600 14px/1.4 ' + FONT + ';color:#1b2430',
  hint: 'font:400 12px/1.4 ' + FONT + ';color:#5b6673;margin:2px 0 0',
  body: 'padding:14px',
  row:  'display:flex;flex-wrap:wrap;gap:12px',
  tile: 'flex:1 1 150px;min-width:150px;border:1px solid #e3e7ee;border-radius:8px;padding:10px 12px;background:#fbfcfe',
  tbd:  'flex:1 1 150px;min-width:150px;border:1px dashed #c4ccd6;border-radius:8px;padding:10px 12px;background:#fafbfc',
  kLabel: 'font:600 11px/1.4 ' + FONT + ';color:#5b6673;text-transform:uppercase;letter-spacing:.04em',
  kValue: 'font:700 22px/1.3 ' + FONT + ';color:#0f172a;margin:2px 0 6px',
  small: 'font:13px/1.55 ' + FONT + ';color:#26303c',
  muted: 'font:12px/1.5 ' + FONT + ';color:#5b6673',
  track: 'height:8px;border-radius:4px;background:#e6eaf0;overflow:hidden',
};
Object.keys(S).forEach(k => { if (!/;\s*$/.test(S[k])) S[k] += ';'; });
const card = (title, hint, inner) =>
  '<section style="' + S.card + '"><div style="' + S.head + '">' + esc(title) +
  (hint ? '<div style="' + S.hint + '">' + esc(hint) + '</div>' : '') + '</div>' +
  '<div style="' + S.body + '">' + inner + '</div></section>';
const meter = (pct) =>
  '<div style="' + S.track + '"><div style="height:8px;border-radius:4px;background:#2f6fed;width:' +
  Math.max(0, Math.min(100, Number(pct) || 0)) + '%"></div></div>';
// donut ring (inline SVG, self-contained): track circle + progress arc from 12 o'clock, value centered
const donut = (pct, valueText) => {
  const p = Math.max(0, Math.min(100, Number(pct) || 0));
  const r = 30, c = 2 * Math.PI * r;
  return '<svg width="76" height="76" viewBox="0 0 76 76" role="img" aria-label="' + p + ' of 100">' +
    '<circle cx="38" cy="38" r="' + r + '" fill="none" stroke="#e6eaf0" stroke-width="8"></circle>' +
    (p > 0 ? '<circle cx="38" cy="38" r="' + r + '" fill="none" stroke="#2f6fed" stroke-width="8" stroke-linecap="round"' +
      ' stroke-dasharray="' + ((p / 100) * c).toFixed(1) + ' ' + c.toFixed(1) + '" transform="rotate(-90 38 38)"></circle>' : '') +
    '<text x="38" y="44" text-anchor="middle" style="font:700 18px ' + FONT + ';fill:#0f172a">' + valueText + '</text></svg>';
};
const donutTile = (label, v) =>
  '<div style="' + S.tile + 'display:flex;flex-direction:column;align-items:center;text-align:center">' +
  '<div style="' + S.kLabel + '">' + esc(label) + '</div>' +
  '<div style="margin-top:6px">' + donut(v, (v === null || v === undefined ? '&mdash;' : Math.round(Number(v)))) + '</div></div>';
const tile = (label, value, sub, meterPct) =>
  '<div style="' + S.tile + '"><div style="' + S.kLabel + '">' + esc(label) + '</div>' +
  '<div style="' + S.kValue + '">' + value + '</div>' +
  (meterPct === undefined ? '' : meter(meterPct)) +
  (sub ? '<div style="' + S.muted + 'margin-top:6px">' + sub + '</div>' : '') + '</div>';
const tbd = (label, hint) =>
  '<div style="' + S.tbd + '"><div style="' + S.kLabel + '">' + esc(label) + '</div>' +
  '<div style="font:700 16px/1.4 ' + FONT + ';color:#8a94a1;margin:4px 0 2px">TBD</div>' +
  '<div style="' + S.muted + '">' + esc(hint) + '</div></div>';
const doneMark = (d) => d
  ? '<span style="color:#1a7f37;font-weight:600">&#10003; done</span>'
  : '<span style="color:#b45309;font-weight:600">&#9675; open</span>';
const list = (items) => items.length
  ? '<ul style="margin:4px 0 0;padding-left:18px;' + S.small + '">' + items.join('') + '</ul>'
  : '<div style="' + S.muted + '">none</div>';

// ---- Row 1 · Routine Notes analytics ----
